def main():
    N = int(input())

    total_X = 0
    total_Y = 0
    for i in range(N):
        x, y = map(int, input().split())
        total_X += x
        total_Y += y

    if total_X > total_Y:
        print("Takahashi")
    elif total_X == total_Y:
        print("Draw")
    else:
        print("Aoki")
